function renderTree(){if(!treeRoot)return;function nodeHtml(n){const open=expanded.has(n.id),ids=descendants(n,[]),checked=ids.length&&ids.every(id=>selected.has(id)),some=ids.some(id=>selected.has(id));return `<div class="node"><div class="node-row ${currentFolder===n.id?'active':''}" data-folder="${n.id}"><span class="twisty" data-toggle="${n.id}">${n.folders.length?(open?'▼':'▶'):''}</span><input type="checkbox" data-folder-check="${n.id}" ${checked?'checked':''} ${some&&!checked?'data-indeterminate="1"':''}><span class="folder-icon">📁</span><span>${esc(n.name)}</span><span class="count">(${ids.length})</span></div>${open?`<div class="children">${n.folders.map(nodeHtml).join('')}</div>`:''}</div>`}$('tree').innerHTML=`<div class="node-row ${currentFolder==='__ALL__'?'active':''}" data-folder="__ALL__"><span class="twisty"></span><span class="folder-icon">▣</span><b>Alle IFC-filer</b><span class="count">(${rows.length})</span></div>${nodeHtml(treeRoot)}`;$('tree').querySelectorAll('[data-indeterminate]').forEach(x=>x.indeterminate=true);$('tree').querySelectorAll('[data-toggle]').forEach(x=>x.onclick=e=>{e.stopPropagation();const id=x.dataset.toggle;expanded.has(id)?expanded.delete(id):expanded.add(id);renderTree()});$('tree').querySelectorAll('[data-folder]').forEach(x=>x.onclick=e=>{if(e.target.matches('input,[data-toggle]'))return;folderFilters.clear();currentFolder=x.dataset.folder;renderTree();renderTable()});$('tree').querySelectorAll('[data-folder-check]').forEach(x=>x.onchange=e=>{e.stopPropagation();const n=findNode(treeRoot,x.dataset.folderCheck),ids=descendants(n,[]);if(x.checked){folderFilters.add(n.id);ids.forEach(id=>selected.add(id))}else{folderFilters.delete(n.id);ids.forEach(id=>selected.delete(id))}currentFolder='__ALL__';updateSelection();renderTree();renderTable()})}
function colDefs(){const base={name:{label:'Filnavn',get:r=>r.file.name,type:'text'},format:{label:'Format',get:r=>r.file.format,type:'text'}};for(const c of columnConfig.filter(c=>c.visible!==false))base[c.id]={label:c.title,get:r=>valueForColumn(r,c),type:c.id==='mmi'?'number':c.id==='revisjonsdato'?'date':'text'};return base}
function filterValue(v){return v===undefined||v===null||String(v).trim()===''||String(v)==='-'?'(tom)':String(v)}
function parseDate(v){const s=String(v||'').trim();let m;if((m=s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})$/)))return Date.UTC(+m[3],+m[2]-1,+m[1]);if((m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/)))return Date.UTC(+m[1],+m[2]-1,+m[3]);const t=Date.parse(s);return Number.isNaN(t)?null:t}
