function renderTable(){const a=visibleRows(),n=currentFolder==='__ALL__'?null:findNode(treeRoot,currentFolder);$('currentFolder').textContent=folderFilters.size?`Valgte mapper: ${folderFilters.size}`:(n?n.path.replace(/^\//,'')||n.name:'Alle filer');$('visibleCount').textContent=`${a.length} filer`;$('selectAll').checked=a.length>0&&a.every(r=>selected.has(r.file.id));$('selectAll').indeterminate=a.some(r=>selected.has(r.file.id))&&!a.every(r=>selected.has(r.file.id));$('body').innerHTML=a.map(r=>`<tr class="${selected.has(r.file.id)?'selected':''}" data-file="${r.file.id}"><td><input type="checkbox" data-file-check="${r.file.id}" ${selected.has(r.file.id)?'checked':''}></td><td><div class="file-cell"><span>📄</span><b>${esc(r.file.name)}</b></div></td><td><span class="format">${esc((r.file.format||'').toUpperCase())}</span></td><td>${r.file.format==='ifc'?'klar for 3D':'ikke 3D-modell'}</td>${columnConfig.filter(c=>c.visible!==false).map(c=>renderMetaCell(r,c)).join('')}</tr>`).join('')||'<tr><td colspan="20">Ingen treff</td></tr>';$('body').querySelectorAll('[data-file-check]').forEach(x=>x.onchange=()=>{x.checked?selected.add(x.dataset.fileCheck):selected.delete(x.dataset.fileCheck);updateSelection();renderTree();renderTable()});$('body').querySelectorAll('[data-file]').forEach(tr=>tr.onclick=e=>{if(e.target.matches('input'))return;const id=tr.dataset.file;selected.has(id)?selected.delete(id):selected.add(id);updateSelection();renderTree();renderTable()})}
