function buildViewerUrl(includeVersions=true, onlyModel=null){const chosen=selectedRows();if(!chosen.length)throw Error('Ingen filer er valgt');let models=chosen.filter(r=>r.file.format==='ifc');if(onlyModel)models=models.filter(r=>String(r.file.id)===String(onlyModel));if(!models.length)throw Error('Ingen valgte IFC-modeller kan åpnes i 3D-vieweren');const projectId=String(project?.id||'').trim();if(!projectId)throw Error('Mangler projectId');const modelIds=models.map(r=>String(r.file.id));const versionIds=models.map(r=>r.file.versionId?String(r.file.versionId):'');const base=`https://web.connect.trimble.com/projects/${encodeURIComponent(projectId)}/viewer/3d/`;const useVersions=includeVersions&&versionIds.length===modelIds.length&&versionIds.every(Boolean);const query=[`projectId=${encodeURIComponent(projectId)}`,`modelId=${modelIds.map(encodeURIComponent).join(',')}`];if(useVersions)query.push(`versionId=${versionIds.map(encodeURIComponent).join(',')}`);const url=`${base}?${query.join('&')}`;log('VIEWER DEEPLINK',{mode:onlyModel?'single':(useVersions?'with-version':'without-version'),projectId,modelCount:modelIds.length,modelIds,versionIdsIncluded:useVersions,versionIds,url});return{url,modelCount:modelIds.length,modelIds}}
