function updateSelection(){$('selectionCount').textContent=`${selected.size} ${selected.size===1?'modell':'modeller'} valgt`}function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
