function publisherCanonical(value){if(Array.isArray(value))return '['+value.map(publisherCanonical).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+publisherCanonical(value[k])).join(',')+'}';return JSON.stringify(value)}
function publisherValidateConfig(cfg){if(cfg?.schema!=='DocLibProjectConfiguration'||cfg.schemaVersion!==1||!Array.isArray(cfg.profiles))throw Error('Ugyldig prosjektindeks. Ingen filer er endret.');const ids=new Set();for(const e of cfg.profiles){if(!e||typeof e.id!=='string'||!e.id.trim()||ids.has(e.id)||typeof e.name!=='string'||typeof e.file!=='string')throw Error('Prosjektindeksen har ugyldige eller dupliserte profiloppføringer.');publisherSafePath(e.file);ids.add(e.id)}return cfg}
