function publisherValidateProfile(p){const out=validateImportedProfile({profile:p});if(out.columns.length!==p.columns.length)throw Error('En eller flere kolonner er ugyldige.');const ids=new Set(['name','format']);for(const c of out.columns){if(!c.id.trim()||ids.has(c.id)||!c.title.trim())throw Error('Kolonne-ID må være unik og navn må være utfylt.');ids.add(c.id);if(c.aliases&&!c.aliases.every(a=>typeof a==='string'))throw Error('Ugyldige egenskapsalias.')}const sortable=new Set(['name','format',...out.columns.filter(c=>c.visible!==false).map(c=>c.id)]);if(!sortable.has(out.sort.key)||![-1,1].includes(out.sort.dir))out.sort={key:null,dir:0};return out}
async function publisherReadContext(){const r=await req(`${CORE}/projects/${encodeURIComponent(project.id)}`);if(!r.ok)throw Error('Kunne ikke lese prosjektet.');const rootId=r.data?.rootId||r.data?.rootFolder?.id||r.data?.rootFolderId;if(!rootId)throw Error('Prosjektet mangler rotmappe.');const root=await cfgFolder(rootId,PROJECT_CONFIG_PRIMARY)||await cfgFolder(rootId,PROJECT_CONFIG_FALLBACK);if(!root)return {folder:PROJECT_CONFIG_PRIMARY,doclib:null,configFile:null,config:{schema:'DocLibProjectConfiguration',schemaVersion:1,profiles:[]}};const dl=await cfgFolder(root.id,'DocLib');if(!dl)return {folder:root.name,doclib:null,configFile:null,config:{schema:'DocLibProjectConfiguration',schemaVersion:1,profiles:[]}};const cf=await cfgFile(dl.id,'doclib.config.json');const config=cf?publisherValidateConfig(await readCfgJson(cf)):{schema:'DocLibProjectConfiguration',schemaVersion:1,profiles:[]};return {folder:root.name,doclib:dl,configFile:cf,config}}
