async function openPublisher(){if(publisherBusy)return;if(isProjectProfile())return status('Lag en personlig kopi før du forbereder publisering.','bad');publisherSession=null;$('publisher').classList.add('open');$('publisherPrepare').disabled=true;$('publisherVerify').disabled=true;publisherSetMessage('Leser gjeldende prosjektindeks. Ingen skrivekall utføres.');try{const source=publisherValidateProfile(captureProfile()),sourceName=activeProfile,context=await publisherReadContext();publisherSession={source,sourceName,context,projectId:String(project.id),baseline:publisherCanonical(context.config)};$('publisherSource').textContent=sourceName;$('publisherName').value=sourceName;$('publisherDescription').value='';$('publisherDefault').checked=false;$('publisherMode').value='new';$('publisherTarget').innerHTML=context.config.profiles.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('');$('publisherMode').querySelector('option[value="update"]').disabled=!context.config.profiles.length;publisherUpdateMode();$('publisherPrepare').disabled=false;publisherSetMessage('Forhåndsversjon: lager en ZIP for manuell opplasting. Automatisk publisering er ikke aktivert.')}catch(e){publisherSetMessage(e.message);log('PUBLISHER PREPARE ERROR',{message:e.message})}}
function publisherUpdateMode(){const update=$('publisherMode').value==='update';$('publisherTarget').disabled=!update;if(update&&publisherSession){const e=publisherSession.context.config.profiles.find(x=>x.id===$('publisherTarget').value);if(e)$('publisherName').value=e.name}}
function publisherBuildPackage(session,opts,uid){if(!opts.name?.trim())throw Error('Skriv inn profilnavn.');const config=cloneData(session.context.config),updating=opts.mode==='update';let entry;if(updating){entry=config.profiles.find(e=>e.id===opts.target);if(!entry)throw Error('Målprofilen finnes ikke lenger.')}else{const id='profile-'+uid;if(config.profiles.some(e=>e.id===id))throw Error('Profil-ID finnes allerede.');if(config.profiles.some(e=>e.name.trim().toLowerCase()===opts.name.trim().toLowerCase()))throw Error('Profilnavnet finnes. Velg Oppdater eksisterende eller et annet navn.');entry={id,name:opts.name.trim(),file:`profiles/${id}.json`,enabled:true};config.profiles.push(entry)}entry.name=opts.name.trim();entry.enabled=true;publisherSafePath(entry.file);if(opts.makeDefault)config.defaultProfile=entry.id;const profile={schema:'DocLibProfile',schemaVersion:1,id:entry.id,name:entry.name,description:opts.description||'',profile:cloneData(session.source)};publisherValidateConfig(config);publisherValidateProfile(profile.profile);return {config,profile,path:entry.file,id:entry.id}}
function publisherCrc(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0}
function publisherZip(files){const encoder=new TextEncoder(),chunks=[],central=[];let offset=0;for(const f of files){const name=encoder.encode(f.name),data=encoder.encode(f.text),crc=publisherCrc(data),header=new Uint8Array(30),v=new DataView(header.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);chunks.push(header,name,data);const ch=new Uint8Array(46),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(14,33,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);central.push(ch,name);offset+=header.length+name.length+data.length}const size=central.reduce((n,x)=>n+x.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'})}
async function preparePublisherPackage(){if(publisherBusy||!publisherSession)return;publisherBusy=true;$('publisherPrepare').disabled=true;try{const s=publisherSession;if(String(project.id)!==s.projectId)throw Error('Prosjektet er endret. Åpne dialogen på nytt.');const current=await publisherReadContext();if(publisherCanonical(current.config)!==s.baseline)throw Error('Prosjektindeksen er endret. Lukk og åpne dialogen på nytt.');const opts={mode:$('publisherMode').value,target:$('publisherTarget').value,name:$('publisherName').value,description:$('publisherDescription').value,makeDefault:$('publisherDefault').checked},pack=publisherBuildPackage(s,opts,crypto.randomUUID()),base=s.context.folder+'/DocLib/';const instructions=`MANUELL PUBLISERING - IKKE AUTOMATISK PUBLISERT\nProsjekt: ${s.projectId}\nProfil: ${pack.profile.name}\n\nKontroller at doclib.config.json ikke er endret etter at pakken ble laget.\nLast opp profilfilen ${base+pack.path} først.\nLast opp ${base}doclib.config.json sist.\nBehold øvrige profiler og mapper.\nKontroller lesetilgang for prosjektmedlemmer og skrivetilgang for forvaltere.\nTrykk Kontroller opplastede filer i DocLib etter opplasting.\nPakken beskytter ikke mot samtidige manuelle opplastinger.\n`;const files=[{name:base+pack.path,text:JSON.stringify(pack.profile,null,2)},{name:base+'doclib.config.json',text:JSON.stringify(pack.config,null,2)},{name:'LES_MEG.txt',text:instructions}],blob=publisherZip(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`DocLib_project_profile_${safeFileName(pack.profile.name)}.zip`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);s.prepared=pack;$('publisherVerify').disabled=false;publisherSetMessage('Filpakke laget, ikke publisert. Last opp profilfilen først og indeksen sist. Bruk deretter kontrollknappen.')}catch(e){publisherSetMessage(e.message);log('PUBLISHER PACKAGE ERROR',{message:e.message})}finally{publisherBusy=false;$('publisherPrepare').disabled=false}}
async function verifyPublisherPackage(){if(publisherBusy||!publisherSession?.prepared)return;publisherBusy=true;$('publisherVerify').disabled=true;try{const s=publisherSession,p=s.prepared;if(String(project.id)!==s.projectId)throw Error('Prosjektet er endret.');const current=await publisherReadContext();if(publisherCanonical(current.config)!==publisherCanonical(p.config))throw Error('Prosjektindeksen samsvarer ikke med pakken. Ingen publisering er bekreftet.');const f=await resolveCfgFile(current.doclib.id,p.path),actual=await readCfgJson(f);if(publisherCanonical(actual)!==publisherCanonical(p.profile))throw Error('Profilfilen samsvarer ikke med pakken.');publisherSetMessage('Bekreftet: både profilfilen og prosjektindeksen samsvarer med pakken. Last DocLib på nytt for å oppdatere prosjektprofilene.')}catch(e){publisherSetMessage(e.message)}finally{publisherBusy=false;$('publisherVerify').disabled=false}}
function closePublisher(){if(!publisherBusy){$('publisher').classList.remove('open');publisherSession=null}}

async function init(){try{wireSingleUpload();$('publisherOpen').onclick=openPublisher;$('publisherClose').onclick=closePublisher;$('publisherMode').onchange=publisherUpdateMode;$('publisherTarget').onchange=publisherUpdateMode;$('publisherPrepare').onclick=preparePublisherPackage;$('publisherVerify').onclick=verifyPublisherPackage;$('refresh').onclick=()=>load(true).catch(fail);$('diagToggle').onclick=$('closeDiag').onclick=()=>{$('diag').style.display=$('diag').style.display==='block'?'none':'block'};$('clearLog').onclick=()=>{lines=[];$('log').textContent=''};$('clearSelection').onclick=()=>{selected.clear();updateSelection();renderTree();renderTable()};$('clearFolders').onclick=()=>{folderFilters.clear();currentFolder='__ALL__';renderTree();renderTable()};$('formatButton').onclick=e=>{e.stopPropagation();$('formatMenu').classList.toggle('open')};document.addEventListener('click',e=>{if(!e.target.closest('.dropdown'))$('formatMenu').classList.remove('open')});$('showSelected').onclick=()=>{try{openSelectedInViewer(true)}catch(e){fail(e)}};$('showNoVersion').onclick=()=>{try{openSelectedInViewer(false)}catch(e){fail(e)}};$('testSingles').onclick=()=>{try{testSelectedIndividually()}catch(e){fail(e)}};$('resetFilters').onclick=resetFilters;$('settingsBtn').onclick=openSettings;$('discoveryBtn').onclick=openDiscovery;$('analyticsBtn').onclick=openAnalytics;$('analyticsClose').onclick=()=>$('analytics').classList.remove('open');$('discoveryClose').onclick=()=>$('discovery').classList.remove('open');$('settingsClose').onclick=()=>$('settings').classList.remove('open');$('settingsApply').onclick=applySettings;$('settingsAdd').onclick=addColumn;$('settingsReset').onclick=resetColumns;$('profileSelect').onchange=e=>switchProfile(e.target.value);$('profileSaveAs').onclick=saveProfileAs;$('profileRename').onclick=renameProfile;$('profileDelete').onclick=deleteProfile;$('profileCopyLocal').onclick=copyProjectProfileToLocal;$('profileExport').onclick=()=>{try{exportActiveProfile()}catch(e){fail(e)}};$('profileImport').onclick=triggerProfileImport;$('profileImportFile').onchange=e=>importProfileFile(e.target.files?.[0]).catch(fail);$('importConflictApply').onclick=confirmProfileImport;$('importConflictCancel').onclick=cancelProfileImport;$('importConflictClose').onclick=cancelProfileImport;wireHeaders();document.addEventListener('click',e=>{if(!e.target.closest('.colhead'))document.querySelectorAll('.column-menu.open').forEach(x=>x.classList.remove('open'))});$('search').oninput=renderTable;$('selectAll').onchange=e=>{visibleRows().forEach(r=>e.target.checked?selected.add(r.file.id):selected.delete(r.file.id));updateSelection();renderTree();renderTable()};$('expandAll').onclick=()=>{allExpanded=!allExpanded;expanded.clear();if(allExpanded){(function add(n){expanded.add(n.id);n.folders.forEach(add)})(treeRoot)}else expanded.add('__ROOT__');renderTree()};status('Kobler til Workspace API...');API=await TrimbleConnectWorkspace.connect(window.parent,(e,a)=>log('WORKSPACE EVENT',{event:e,args:a}),30000);await registerMenu();project=API.project.getProject?await API.project.getProject():await API.project.getCurrentProject();token=await auth();if(!token)throw Error('Mangler Trimble ID access token');await load(false);renderProfileControls();renderDynamicHeaders()}catch(e){fail(e)}}function fail(e){const info=errorInfo(e);log('FEIL',info);status('Feil: '+(info.message||info.string||'ukjent feil'),'bad')}

// Controlled single-file upload. SDK 4.0.12 TCPS.uploadFileContent wire contract.
// Legacy initiate/commit are deprecated. No fallback, overwrite, index write or retry.
let singleUpload=null,singleBusy=false;
function singleReceiptKey(){return 'doclib-single-upload:'+String(project.id)}
function singleMessage(text){$('singleMessage').textContent=text}
function singleReceipt(){try{return JSON.parse(localStorage.getItem(singleReceiptKey())||'null')}catch{return null}}
function singleSaveReceipt(r){localStorage.setItem(singleReceiptKey(),JSON.stringify(r))}
async function singleItems(id){const r=await fetch(`${CORE}/folders/${encodeURIComponent(id)}/items`,{headers:{Authorization:`Bearer ${token}`,Accept:'application/json'},cache:'no-store'});if(!r.ok)throw Error(`Kan ikke lese målmappe (HTTP ${r.status}).`);const data=await r.json();if(r.status===206)throw Error('Delvis mappeliste. Opplasting stoppet for å unngå ufullstendig kollisjonskontroll.');return arr(data)}
async function singleBrowse(id,path){if(singleBusy)return;const items=await singleItems(id);singleUpload.folderId=id;singleUpload.path=path;singleUpload.items=items;$('singlePath').textContent=path;$('singleFolders').innerHTML='<option value="">Velg undermappe...</option>'+items.filter(x=>x.type==='FOLDER').map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');singleSummary()}
function singleSummary(){if(!singleUpload)return;const s=singleUpload;$('singleSummary').textContent=`Prosjekt: ${s.projectName} (${s.projectId})\nKilde: ${s.sourceName}\nMål: ${s.path}/${s.name}\nKolonner: ${s.payload.profile.columns.length}\nIndeks og eksisterende profiler endres ikke.`;$('singleStart').disabled=singleBusy||s.attempted||!$('singleConsent').checked}
async function openSingleUpload(){if(singleBusy)return;if(isProjectProfile())return status('Lag en personlig kopi først.','bad');$('singleUpload').classList.add('open');$('singleStart').disabled=true;$('singleConsent').checked=false;singleUpload=null;singleMessage('Leser prosjekt og mapper. Ingen skrivekall utføres.');try{const profile=publisherValidateProfile(captureProfile()),r=await req(`${CORE}/projects/${encodeURIComponent(project.id)}`);if(!r.ok)throw Error('Kan ikke lese prosjekt.');const rootId=r.data?.rootId||r.data?.rootFolder?.id||r.data?.rootFolderId;if(!rootId)throw Error('Fant ingen rotmappe.');const id='profile-'+crypto.randomUUID();singleUpload={projectId:String(project.id),projectName:r.data.name||String(project.id),rootId,sourceName:activeProfile,name:id+'.json',payload:{schema:'DocLibProfile',schemaVersion:1,id,name:activeProfile,profile:cloneData(profile)},attempted:false};await singleBrowse(rootId,r.data.name||'Prosjekt');const receipt=singleReceipt();$('singleVerify').disabled=!receipt;singleMessage(receipt?`Tidligere forsøk: ${receipt.name} (${receipt.stage}). Kontroller dette før du eventuelt oppretter en ny fil.`:'Velg en eksisterende testmappe. Bekreft sammendraget før opplasting.')}catch(e){singleUpload=null;singleMessage(e.message)}}
async function singlePost(path,body){const r=await fetch(CORE+path,{method:'POST',headers:{Authorization:`Bearer ${token}`,Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(body),redirect:'error'});log('SINGLE_UPLOAD HTTP',{path,status:r.status});if(!r.ok)throw Error(`Skriveoperasjon avvist (HTTP ${r.status}). Ingen automatisk gjentakelse.`);return await r.json()}
async function singleVerifyReceipt(){if(singleBusy)return;singleBusy=true;try{await singleVerifyCore()}catch(e){singleMessage(e.message)}finally{singleBusy=false;singleSummary()}}
async function singleVerifyCore(){const r=singleReceipt();if(!r||r.projectId!==String(project.id))throw Error('Ingen kvittering for dette prosjektet.');const matches=(await singleItems(r.folderId)).filter(x=>x.type==='FILE'&&x.name===r.name);if(matches.length!==1)throw Error(`Fant ${matches.length} filer med forventet navn. Ikke bekreftet. Kontroller mappen manuelt; ikke last opp på nytt automatisk.`);const f=matches[0];if(r.fileId&&String(f.id)!==String(r.fileId))throw Error('Fil-ID avviker fra kvitteringen.');const actual=await readCfgJson(f);if(publisherCanonical(actual)!==publisherCanonical(r.payload))throw Error('Innhold avviker. Ikke bekreftet.');r.fileId=f.id;r.stage='verified';singleSaveReceipt(r);singleMessage(`Profilfil lastet opp og kontrollert. Ikke aktivert som prosjektprofil.\nFil: ${r.path}/${r.name}\nFil-ID: ${r.fileId}\nProsjektindeksen er ikke endret.`);log('SINGLE_UPLOAD VERIFIED',{fileId:f.id,name:r.name,folderId:r.folderId})}
async function startSingleUpload(){const s=singleUpload;if(singleBusy||!s||s.attempted||!$('singleConsent').checked)return;singleBusy=true;singleSummary();let receipt;try{if(String(project.id)!==s.projectId)throw Error('Prosjektet er endret. Åpne dialogen på nytt.');const items=await singleItems(s.folderId);if(items.some(x=>String(x.name).toLowerCase()===s.name.toLowerCase()))throw Error('Filnavnet finnes allerede. Ingen opplasting utført.');publisherValidateProfile(s.payload.profile);receipt={projectId:s.projectId,folderId:s.folderId,path:s.path,name:s.name,payload:s.payload,stage:'initiating'};singleSaveReceipt(receipt);s.attempted=true;singleMessage('Starter én opplasting. Ikke lukk eller last siden på nytt.');const init=await singlePost('/files/fs/initiate',{parentId:s.folderId,parentType:'FOLDER',name:s.name});if(!init.uploadId||typeof init.uploadURL!=='string')throw Error('Uventet initiate-respons. Stoppet uten reserveforsøk.');const url=new URL(init.uploadURL);if(url.protocol!=='https:'||url.username||url.password)throw Error('Ugyldig opplastingsadresse.');receipt.stage='put';receipt.uploadId=init.uploadId;singleSaveReceipt(receipt);const body=new Blob([JSON.stringify(s.payload,null,2)],{type:'application/json'});const put=await fetch(url.href,{method:'PUT',body,credentials:'omit',redirect:'error'});log('SINGLE_UPLOAD PUT',{status:put.status});if(!put.ok)throw Error(`Filoverføring feilet (HTTP ${put.status}).`);receipt.stage='committing';singleSaveReceipt(receipt);const committed=await singlePost('/files/fs/commit',{uploadId:init.uploadId});receipt.stage='committed';if(committed?.id)receipt.fileId=committed.id;singleSaveReceipt(receipt);$('singleVerify').disabled=false;await singleVerifyCore()}catch(e){singleMessage(`${e.message}\n${s.attempted?'Resultatet er ikke bekreftet. Ingen automatisk gjentakelse eller sletting. Bruk Kontroller siste forsøk og kontroller målmappe før nytt forsøk.':'Ingen skrivekall utført.'}`);log('SINGLE_UPLOAD STOP',{stage:receipt?.stage||'preflight',name:s.name});$('singleVerify').disabled=!singleReceipt()}finally{singleBusy=false;singleSummary()}}
function wireSingleUpload(){$('singleOpen').onclick=openSingleUpload;$('singleClose').onclick=()=>{if(!singleBusy)$('singleUpload').classList.remove('open')};$('singleConsent').onchange=singleSummary;$('singleStart').onclick=startSingleUpload;$('singleVerify').onclick=singleVerifyReceipt;$('singleRoot').onclick=()=>{if(singleUpload&&!singleBusy)singleBrowse(singleUpload.rootId,singleUpload.projectName).catch(e=>singleMessage(e.message))};$('singleFolders').onchange=e=>{const f=singleUpload?.items.find(x=>String(x.id)===e.target.value&&x.type==='FOLDER');if(f)singleBrowse(f.id,singleUpload.path+'/'+f.name).catch(e=>singleMessage(e.message))}}

window.addEventListener('load',init);
